import React, { useState, useEffect } from "react";
import { TextField, Button, Typography, Snackbar } from "@mui/material";
import axios from "axios";
import LoadingBar from "./LoadingBar";
import ScreenshotDisplay from "./ScreenshotDisplay";
import "./../styles/AdForm.css";

const AdForm: React.FC = () => {
  const [price, setPrice] = useState<string>("");
  const [description, setDescription] = useState<string>("");
  const [loading, setLoading] = useState<boolean>(false);
  const [submitted, setSubmitted] = useState<boolean>(false);
  const [screenshot, setScreenshot] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [snackbarOpen, setSnackbarOpen] = useState<boolean>(false);
  const [notificationMessage, setNotificationMessage] = useState<string>("");

  // Disable "Publicar" button if fields are empty or if already submitted
  const isSubmitDisabled = !price || !description || submitted || loading;

  // Handle form submission
  const handleSubmit = async (event: React.FormEvent) => {
    event.preventDefault();
    setLoading(true);
    setSubmitted(true);
    setError(null);

    setNotificationMessage("Enviando anuncio...");
    setSnackbarOpen(true); // Open the snackbar when sending data

    try {
      const response = await axios.post("http://localhost:4000/publishAd", {
        price,
        description,
      });

      const { message } = response.data;
      setScreenshot(message); // Set the screenshot to display
      setNotificationMessage("Anuncio publicado con éxito");
    } catch (err) {
      setError("Error: Failed to submit ad. Please try again.");
      setNotificationMessage("Error al enviar el anuncio");
    } finally {
      setLoading(false); // Hide loading bar
    }
  };

  // Handle input changes to re-enable "Publicar" button after submission
  const handlePriceChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setPrice(e.target.value);
    setSubmitted(false); // Re-enable submission when value changes
  };

  const handleDescriptionChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setDescription(e.target.value);
    setSubmitted(false); // Re-enable submission when value changes
  };

  // Close the snackbar notification
  const handleCloseSnackbar = () => {
    setSnackbarOpen(false);
  };

  return (
    <div className="ad-form-container">
      <Typography variant="h4" gutterBottom>
        Publicar Anuncio
      </Typography>

      <form onSubmit={handleSubmit}>
        <TextField
          label="Precio"
          variant="outlined"
          value={price}
          onChange={handlePriceChange}
          fullWidth
          margin="normal"
          required
        />

        <TextField
          label="Descripción"
          variant="outlined"
          value={description}
          onChange={handleDescriptionChange}
          multiline
          rows={4}
          fullWidth
          margin="normal"
          required
        />

        <Button
          type="submit"
          variant="contained"
          color="primary"
          disabled={isSubmitDisabled}
          fullWidth
        >
          Publicar
        </Button>
      </form>

      {/* Loading Bar */}
      {loading && <LoadingBar />}

      {/* Error Message */}
      {error && (
        <Typography color="error" className="error-message">
          {error}
        </Typography>
      )}

      {/* Screenshot Display */}
      {screenshot && <ScreenshotDisplay screenshot={screenshot} />}

      {/* Snackbar Notification positioned at the top-left */}
      <Snackbar
        open={snackbarOpen}
        autoHideDuration={4000}
        onClose={handleCloseSnackbar}
        message={notificationMessage}
        anchorOrigin={{ vertical: "top", horizontal: "left" }} // Position at top-left
      />
    </div>
  );
};

export default AdForm;
